// ============================================================================
// audio-catalog.js — real reciter catalog (Phase 4). The bundled manifest
// (assets/audio/catalog.json, generated by scripts/tools/fetch-audio.mjs from
// LIVE-verified EveryAyah folders) drives the reciters table + pack downloads:
//   Web: per-ayah bytes → OPFS AudioStore (bridge.audioStore)
//   Electron: same catalog, bytes land on disk via the preload bridge
// Starter pack (Al-Fatiha · Alafasy) ships inside the bundle → the player
// works fully offline on first boot; every other pack is an explicit
// user-initiated download. Never background fetches.
// ============================================================================
import { state, nowMs } from '../app-state.js';

let CATALOG = null;

export async function loadCatalog() {
  if (CATALOG) return CATALOG;
  const res = await fetch(new URL('../../assets/audio/catalog.json', import.meta.url));
  if (!res.ok) throw new Error(`catalog fetch failed: HTTP ${res.status}`);
  CATALOG = await res.json();
  return CATALOG;
}

/** Boot sync: catalog → reciters rows + starter pack state (idempotent). */
export async function syncReciters(db) {
  const cat = await loadCatalog();
  for (const r of cat.reciters) {
    await db.write(
      `INSERT INTO reciters (reciter_id, name_ar, name_en, style, word_segments_available, manifest_version)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(reciter_id) DO UPDATE SET name_ar = excluded.name_ar, name_en = excluded.name_en,
         style = excluded.style, manifest_version = excluded.manifest_version`,
      [r.reciter_id, r.name_ar, r.name_en, r.style, r.word_segments_available ?? 0, cat.formatVersion],
    );
  }
  const sp = cat.starterPack;
  const existing = await db.queryOne(
    `SELECT 1 AS x FROM audio_packs_state WHERE reciter_id = ? AND scope = 'surah_subset'`, [sp.reciter_id]);
  if (!existing) {
    // Starter files are bundled assets — offline from the first second.
    let bytes = 0;
    try {
      for (let a = 1; a <= sp.ayahs; a++) {
        const url = new URL(`../../${sp.basePrefix}/001${String(a).padStart(3, '0')}.mp3`, import.meta.url);
        bytes += Number((await fetch(url)).headers.get('content-length') ?? 0);
      }
    } catch { bytes = 0; }
    await db.write(
      `INSERT INTO audio_packs_state (reciter_id, scope, status, bytes, surahs_json, updated_at) VALUES (?, 'surah_subset', 'ready', ?, ?, ?)
       ON CONFLICT(reciter_id, scope) DO NOTHING`,
      [sp.reciter_id, bytes, JSON.stringify(sp.surahs), nowMs()],
    );
  }
}

export function catalogFor(reciterId) {
  return CATALOG?.reciters.find((r) => r.reciter_id === reciterId) ?? null;
}

/** URL template → concrete per-ayah URL ({SSSAAA} → 001002). */
function ayahUrl(rec, surah, ayah) {
  return rec.audio_url_template.replace('{SSSAAA}', `${String(surah).padStart(3, '0')}${String(ayah).padStart(3, '0')}`);
}

/** Starter-pack (bundled) ayah URL — offline via SW runtime cache. */
function starterAyahUrl(surah, ayah) {
  const sp = CATALOG.starterPack;
  return new URL(`../../${sp.basePrefix}/${String(surah).padStart(3, '0')}${String(ayah).padStart(3, '0')}.mp3`, import.meta.url).href;
}

function isStarter(reciterId, surah) {
  const sp = CATALOG.starterPack;
  return reciterId === sp.reciter_id && sp.surahs.includes(Number(surah));
}

/**
 * Resolve ayah audio bytes: installed pack → starter asset → remote URL
 * (remote is the documented online fallback; offline users install packs).
 */
export async function getAyahAudio(reciterId, surah, ayah) {
  const stored = await state.bridge.audioStore.get(reciterId, `${surah}-${ayah}`);
  if (stored) return { blob: stored, offline: true };
  if (isStarter(reciterId, surah)) {
    const res = await fetch(starterAyahUrl(surah, ayah));
    if (res.ok) return { blob: await res.blob(), offline: true };
  }
  const rec = catalogFor(reciterId);
  if (!rec) throw new Error('قارئ غير معروف');
  return { blob: null, url: ayahUrl(rec, surah, ayah), offline: false };
}

/** Download one surah for a reciter into the AudioStore (user-initiated). */
export async function downloadSurahPack(db, reciterId, surah, onProgress) {
  const rec = catalogFor(reciterId);
  if (!rec) throw new Error('قارئ غير معروف');
  const s = await db.queryOne(`SELECT ayah_count, name_ar FROM surahs WHERE number = ?`, [surah]);
  if (!s) throw new Error('سورة غير معروفة');
  const total = s.ayah_count;
  const existing = await db.queryOne(
    `SELECT surahs_json FROM audio_packs_state WHERE reciter_id = ? AND scope = 'surah_subset'`, [reciterId]);
  const surahs = new Set(JSON.parse(existing?.surahs_json ?? '[]'));
  if (surahs.has(Number(surah))) return { skipped: true };

  await db.write(
    `INSERT INTO audio_packs_state (reciter_id, scope, status, bytes, surahs_json, updated_at) VALUES (?, 'surah_subset', 'downloading', 0, ?, ?)
     ON CONFLICT(reciter_id, scope) DO UPDATE SET status = 'downloading', updated_at = excluded.updated_at`,
    [reciterId, existing?.surahs_json ?? '[]', nowMs()],
  );

  let bytes = 0;
  try {
    for (let a = 1; a <= total; a++) {
      const url = ayahUrl(rec, surah, a);
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status} — آية ${a}`);
      const buf = await res.arrayBuffer();
      bytes += buf.byteLength;
      await state.bridge.audioStore.put(reciterId, `${surah}-${a}`, new Blob([buf], { type: 'audio/mpeg' }));
      onProgress?.(a, total);
    }
  } catch (e) {
    await db.write(`UPDATE audio_packs_state SET status = 'partial', updated_at = ? WHERE reciter_id = ? AND scope = 'surah_subset'`, [nowMs(), reciterId]);
    throw e;
  }
  surahs.add(Number(surah));
  await db.write(
    `UPDATE audio_packs_state SET status = 'ready', bytes = bytes + ?, surahs_json = ?, updated_at = ? WHERE reciter_id = ? AND scope = 'surah_subset'`,
    [bytes, JSON.stringify([...surahs].sort((x, y) => x - y)), nowMs(), reciterId],
  );
  return { skipped: false, bytes, ayahs: total };
}
